// Package learning holds the Learning app's book catalog and its Sefaria text client.
package learning

import (
	_ "embed"
	"encoding/json"
	"regexp"
	"strconv"
)

// books.json is generated by scripts/build-learning-catalog.mjs, alongside the frontend's catalog.
//
//go:embed books.json
var booksJSON []byte

type book struct {
	Corpus string `json:"corpus"`
	Talmud bool   `json:"talmud"`
	Start  int    `json:"start"` // first section: a chapter number, or for the Talmud an amud index (2 = 2a)
	Count  int    `json:"count"`
}

var books = func() map[string]book {
	m := map[string]book{}
	if err := json.Unmarshal(booksJSON, &m); err != nil {
		panic("learning: invalid books.json: " + err.Error())
	}
	return m
}()

var refRe = regexp.MustCompile(`^([A-Za-z' ]+) (\d{1,3})([ab])?$`)

// ParseRef validates a section ref such as "Genesis 1", "Mishnah Berakhot 2" or "Berakhot 2a"
// against the catalog and returns its corpus. Only whole sections of known books are accepted,
// so the text cache can't be filled with arbitrary Sefaria content such as commentaries.
func ParseRef(ref string) (corpus string, ok bool) {
	m := refRe.FindStringSubmatch(ref)
	if m == nil {
		return "", false
	}
	b, found := books[m[1]]
	if !found || b.Talmud != (m[3] != "") {
		return "", false
	}
	n, _ := strconv.Atoi(m[2])
	index := n
	if b.Talmud {
		index = (n-1)*2 + map[string]int{"a": 0, "b": 1}[m[3]]
	}
	if index < b.Start || index >= b.Start+b.Count {
		return "", false
	}
	return b.Corpus, true
}
